import time
import math
from functools import wraps

def retry_with_backoff(fn, attempts):
    """
    Retries a callable with exponential backoff.

    Args:
        fn (callable): The function to retry.
        attempts (int): The maximum number of attempts.

    Returns:
        callable: A wrapped function that retries `fn`.
    """
    if not callable(fn):
        raise TypeError("fn must be a callable.")
    if not isinstance(attempts, int) or attempts < 1:
        raise ValueError("attempts must be a positive integer.")

    @wraps(fn)
    def wrapper(*args, **kwargs):
        for i in range(attempts):
            try:
                return fn(*args, **kwargs)
            except Exception as e:
                if i == attempts - 1:
                    # If this is the last attempt, re-raise the exception
                    raise e

                # Exponential backoff: 2^i seconds
                sleep_time = math.pow(2, i)
                print(f"Attempt {i+1} failed. Retrying in {sleep_time:.2f} seconds...")
                time.sleep(sleep_time)
    return wrapper

