import functools

def lru_cache_decorator(maxsize):
    """
    A simple LRU (Least Recently Used) cache decorator.

    Args:
        maxsize (int): The maximum number of items to store in the cache.
                       If 0, the cache is disabled. If None, the cache is unbounded.

    Returns:
        callable: A decorator that caches the results of a function.
    """
    if maxsize is None:  # Unbounded cache
        cache = {}
        def decorator(func):
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, frozenset(kwargs.items()))
                if key in cache:
                    return cache[key]
                result = func(*args, **kwargs)
                cache[key] = result
                return result
            return wrapper
        return decorator
    elif maxsize == 0:  # Cache disabled
        def decorator(func):
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
